using UnityEngine; using TMPro; public class PlayerNoteInteractor : MonoBehaviour { public Camera playerCamera; public Transform holdPoint; public TMP_Text instructionText; public float interactDistance = 12f; public KeyCode interactKey = KeyCode.E; private StickyNote highlightedNote; private StickyNote heldNote; void Update() { if (heldNote == null) { UpdateHover(); if (Input.GetKeyDown(interactKey) && highlightedNote != null) { PickUpNote(highlightedNote); } } else { if (instructionText != null) { instructionText.text = "Look at a category board and press E to place"; } if (Input.GetKeyDown(interactKey)) { TryDropNote(); } } } void UpdateHover() { StickyNote newHighlightedNote = null; Ray ray = playerCamera.ViewportPointToRay( new Vector3(0.5f, 0.5f, 0f) ); if (Physics.Raycast( ray, out RaycastHit hit, interactDistance)) { newHighlightedNote = hit.collider.GetComponentInParent<StickyNote>(); } if (newHighlightedNote != highlightedNote) { if (highlightedNote != null) { highlightedNote.SetHighlighted(false); } highlightedNote = newHighlightedNote; if (highlightedNote != null) { highlightedNote.SetHighlighted(true); } } if (instructionText != null) { if (highlightedNote != null) { instructionText.text = "Press E to pick up this note"; } else { instructionText.text = "WASD Move | Mouse Look | E Interact"; } } } void PickUpNote(StickyNote note) { if (note.CurrentZone != null) { note.CurrentZone.RemoveNote(note); } if (highlightedNote != null) { highlightedNote.SetHighlighted(false); } highlightedNote = null; heldNote = note; heldNote.SetHeld(true); heldNote.transform.SetParent(holdPoint); heldNote.transform.localPosition = Vector3.zero; heldNote.transform.localRotation = Quaternion.identity; } void TryDropNote() { Ray ray = playerCamera.ViewportPointToRay( new Vector3(0.5f, 0.5f, 0f) ); CategoryZone targetZone = null; if (Physics.Raycast( ray, out RaycastHit hit, interactDistance)) { targetZone = hit.collider.GetComponentInParent<CategoryZone>(); } if (targetZone != null) { heldNote.SetHeld(false); targetZone.PlaceNote(heldNote); } else { heldNote.SetHeld(false); heldNote.ReturnHome(); } heldNote = null; } }